"""Independent known-value metrics, not fixtures generated by the implementation."""

import math

import pytest

from football.evaluation import metrics, outcome, probabilities


def test_known_three_class_metrics_and_confusion():
    result = metrics(
        [([0.7, 0.2, 0.1], "home_win"), ([0.1, 0.6, 0.3], "draw"), ([0.2, 0.5, 0.3], "away_win")]
    )
    assert result["accuracy"] == pytest.approx(2 / 3)
    assert result["confusion_matrix"] == [[1, 0, 0], [0, 1, 0], [0, 1, 0]]
    assert result["log_loss"] == pytest.approx(-(math.log(0.7) + math.log(0.6) + math.log(0.3)) / 3)
    assert result["brier_score"] == pytest.approx((0.14 + 0.26 + 0.78) / 3)


def test_ties_clipping_and_brier_scaling():
    tied = metrics([([1 / 3, 1 / 3, 1 / 3], "draw")])
    assert tied["accuracy"] == 0
    assert tied["confusion_matrix"] == [[0, 0, 0], [1, 0, 0], [0, 0, 0]]
    assert tied["brier_score"] == pytest.approx(2 / 3)
    impossible = metrics([([1, 0, 0], "away_win")])
    assert impossible["log_loss"] == pytest.approx(-math.log(1e-15))
    assert impossible["brier_score"] == 2
    assert metrics([([0, 1, 0], "draw")])["accuracy"] == 1


@pytest.mark.parametrize(
    "values",
    [
        [],
        ["1", 0, 0],
        [0, 0, 0],
        [1, 1, 0],
        [-0.1, 0.6, 0.5],
        [float("nan"), 0, 1],
        [float("inf"), 0, 0],
        [True, 0, 0],
        [0.4, 0.3, 0.30001],
    ],
)
def test_invalid_probabilities(values):
    with pytest.raises(ValueError):
        probabilities(values)


def test_roundoff_normalization_missing_outcomes_and_empty_metrics():
    assert sum(probabilities([0.5, 0.25, 0.2500000001])) == pytest.approx(1)
    with pytest.raises(ValueError):
        metrics([([1, 0, 0], None)])
    assert metrics([]) == dict(
        accuracy=None, log_loss=None, brier_score=None, confusion_matrix=None
    )


@pytest.mark.parametrize(
    ("home", "away", "expected"), [(2, 1, "home_win"), (0, 0, "draw"), (1, 2, "away_win")]
)
def test_regulation_labels(home, away, expected):
    assert outcome(home, away) == expected


@pytest.mark.parametrize(("home", "away"), [(-1, 0), (True, 0), (1.5, 0)])
def test_invalid_scores(home, away):
    with pytest.raises(ValueError):
        outcome(home, away)
